for title,start,end in rows:add(title,start,end,'admissions','admissions',adm,'U školních zkoušek jde o povolené období; konkrétní den určuje škola.' if 'Školní' in title or 'zkoušky na konzervatoře' in title.lower() else '')
rows=[('Přihláška k jarní maturitě – nejpozději','2026-12-01',None),('Výpis přihlášky – nejpozději','2026-12-21',None),('Registrace na výsledkovém portálu od','2027-01-04',None),('Jarní didaktické testy','2027-05-03','2027-05-06'),('Výsledky didaktických testů školám do','2027-05-15',None),('Jarní profilové zkoušky','2027-05-16','2027-06-10'),('Písemné a praktické zkoušky možné od','2027-04-01',None),('Přihláška k podzimní maturitě – nejpozději','2027-06-25',None),('Výpis podzimní přihlášky – nejpozději','2027-07-07',None),('Podzimní didaktické testy – období','2027-09-01','2027-09-10'),('Podzimní profilové zkoušky – období','2027-09-01','2027-09-20'),('Podzimní písemné a praktické zkoušky možné od','2027-08-25',None),('Podzimní výsledky didaktických testů školám do','2027-09-10',None)]
for title,start,end in rows:add(title,start,end,'maturita','maturita',['SS','KON'],'Podrobný rozpis testů není v této verzi zveřejněn; konkrétní profilové termíny stanovuje škola.' if end else '')
